  cards: [{ q: 'Pre aký trojuholník platí Pytagorova veta?', a: 'Pre pravouhlý.' }, { q: 'Ako sa volá najdlhšia strana pravouhlého trojuholníka?', a: 'Prepona.' }, { q: 'Napíš Pytagorovu vetu.', a: 'c² = a² + b².' }, { q: 'Odvesny sú 6 a 8. Aká je prepona?', a: '10.' }, { q: 'Prepona je 13, odvesna 5. Aká je druhá odvesna?', a: '12.', l: 2 }, { q: 'Je trojuholník so stranami 7, 8, 10 pravouhlý?', a: 'Nie, 49 + 64 = 113 a to sa nerovná 100.', l: 3 }],
